#pragma warning disable CA2100 // The schema name is generated by this fixture.
using System.Text;
using Autonogrammer.Api.Cowork.Artifacts;
using Autonogrammer.Api.Options;
using Autonogrammer.Contracts.Artifacts;
using Autonogrammer.Cowork.Artifacts;
using Autonogrammer.Cowork.Artifacts.Stores;
using Autonogrammer.Sessions.Postgres.Migrations;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;
using Shouldly;
using Xunit;

namespace Autonogrammer.Api.IntegrationTests.Artifacts;

/// <summary>
/// The artifact directory over the real PostgreSQL store. Each request opens its own store, so the quota, the version count and the version number must be
/// decided under a database lock rather than an in-process one. Needs <c>AUTONOGRAMMER_TEST_POSTGRES_CONNECTION</c>.
/// </summary>
public sealed class ArtifactDirectoryPostgresTests : IAsyncLifetime
{
    private readonly string _schema = "t_" + Guid.NewGuid().ToString("N");
    private NpgsqlDataSource? _admin;
    private NpgsqlDataSource? _app;
    private ArtifactAccountDirectory? _directory;

    private static CancellationToken Token => TestContext.Current.CancellationToken;

    /// <inheritdoc />
    public async ValueTask InitializeAsync()
    {
        var configured = Environment.GetEnvironmentVariable("AUTONOGRAMMER_TEST_POSTGRES_CONNECTION");
        if (string.IsNullOrWhiteSpace(configured))
        {
            throw new InvalidOperationException("AUTONOGRAMMER_TEST_POSTGRES_CONNECTION is unset. Source scripts/test-services.sh up before these tests.");
        }

        _admin = NpgsqlDataSource.Create(configured);
        await new MigrationRunner(_admin, _schema).MigrateAsync(CancellationToken.None).ConfigureAwait(false);
        _app = NpgsqlDataSource.Create(new NpgsqlConnectionStringBuilder(configured) { SearchPath = _schema + ",public", MaxPoolSize = 40 }.ConnectionString);
        var services = new ServiceCollection().AddSingleton(_app).BuildServiceProvider();
        _directory = new ArtifactAccountDirectory(Microsoft.Extensions.Options.Options.Create(new SessionsOptions { Store = SessionsOptions.PostgresStore }), services);
    }

    /// <inheritdoc />
    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.DisposeAsync().ConfigureAwait(false);
        }

        if (_admin is null)
        {
            return;
        }

        var drop = _admin.CreateCommand(
            $"""
            DO $drop$
            BEGIN
                IF EXISTS (SELECT 1 FROM timescaledb_information.jobs WHERE hypertable_schema = '{_schema}') THEN
                    PERFORM delete_job(job_id) FROM timescaledb_information.jobs WHERE hypertable_schema = '{_schema}';
                END IF;
                DROP SCHEMA IF EXISTS "{_schema}" CASCADE;
            END
            $drop$;
            """);
        await using (drop.ConfigureAwait(false))
        {
            _ = await drop.ExecuteNonQueryAsync(CancellationToken.None).ConfigureAwait(false);
        }

        await _admin.DisposeAsync().ConfigureAwait(false);
    }

    /// <summary>Parallel uploads of different artifacts cannot all read usage below the account quota and exceed it together.</summary>
    [Fact]
    public async Task ParallelUploadsRespectTheAccountQuota()
    {
        var limits = new ArtifactOptions { MaxAccountBytes = 100 };
        var account = "quota-" + Guid.NewGuid().ToString("N");
        var outcomes = await Task.WhenAll(Enumerable.Range(0, 10).Select(index => PutAsync(account, "q-" + index + "-" + Guid.NewGuid().ToString("N"), 1, Payload(40, index), limits))).ConfigureAwait(true);

        outcomes.Count(outcome => outcome == ArtifactPutOutcome.Created).ShouldBe(2);
        outcomes.Count(outcome => outcome == ArtifactPutOutcome.Quota).ShouldBe(8);
    }

    /// <summary>Parallel uploads of one version with different bytes end with one winner and a conflict for the rest, and no database error.</summary>
    [Fact]
    public async Task ParallelUploadsOfOneVersionConflictInsteadOfFailing()
    {
        var limits = new ArtifactOptions();
        var account = "race-" + Guid.NewGuid().ToString("N");
        var id = "race-" + Guid.NewGuid().ToString("N");
        var outcomes = await Task.WhenAll(Enumerable.Range(0, 6).Select(index => PutAsync(account, id, 1, Payload(10, index), limits))).ConfigureAwait(true);

        outcomes.Count(outcome => outcome == ArtifactPutOutcome.Created).ShouldBe(1);
        outcomes.Count(outcome => outcome == ArtifactPutOutcome.Conflict).ShouldBe(5);
    }

    /// <summary>Parallel uploads of one version with the same bytes end with one creation and the same-hash answer for the rest.</summary>
    [Fact]
    public async Task ParallelUploadsOfTheSameBytesAreIdempotent()
    {
        var limits = new ArtifactOptions();
        var account = "same-" + Guid.NewGuid().ToString("N");
        var id = "same-" + Guid.NewGuid().ToString("N");
        var created = await PutAsync(account, id, 1, Payload(10, 0), limits).ConfigureAwait(true);
        created.ShouldBe(ArtifactPutOutcome.Created);
        var outcomes = await Task.WhenAll(Enumerable.Range(0, 6).Select(_ => PutAsync(account, id, 2, Payload(10, 1), limits))).ConfigureAwait(true);

        outcomes.Count(outcome => outcome == ArtifactPutOutcome.Created).ShouldBe(1);
        outcomes.Count(outcome => outcome == ArtifactPutOutcome.SameHash).ShouldBe(5);
    }

    /// <summary>Version 3 before version 2 is a conflict, and the history reads back once the versions arrive in order.</summary>
    [Fact]
    public async Task OutOfOrderVersionIsRefusedAndHistoryStaysReadable()
    {
        var limits = new ArtifactOptions();
        var account = "order-" + Guid.NewGuid().ToString("N");
        var id = "order-" + Guid.NewGuid().ToString("N");
        (await PutAsync(account, id, 1, Payload(10, 1), limits).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.Created);
        (await PutAsync(account, id, 3, Payload(10, 3), limits).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.Conflict);
        (await PutAsync(account, id, 2, Payload(10, 2), limits).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.Created);
        (await PutAsync(account, id, 3, Payload(10, 3), limits).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.Created);

        var summary = await _directory!.FindAsync(account, id, Token).ConfigureAwait(true);
        summary.ShouldNotBeNull();
        summary.Version.ShouldBe(3);
    }

    /// <summary>The per-kind byte limit and the version count apply to a stored artifact, whatever kind the request names.</summary>
    [Fact]
    public async Task KindLimitAndMaxVersionsApplyToStoredArtifacts()
    {
        var limits = new ArtifactOptions { MaxSvgBytes = 64, MaxVersions = 2 };
        var account = "limits-" + Guid.NewGuid().ToString("N");
        var id = "limits-" + Guid.NewGuid().ToString("N");
        (await PutAsync(account, "svg-big-" + Guid.NewGuid().ToString("N"), 1, Payload(65, 0), limits, ArtifactKind.Svg).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.TooLarge);
        (await PutAsync(account, id, 1, Payload(10, 0), limits, ArtifactKind.Svg).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.Created);
        (await PutAsync(account, id, 2, Payload(65, 1), limits, ArtifactKind.Markdown).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.TooLarge);
        (await PutAsync(account, id, 2, Payload(10, 1), limits, ArtifactKind.Markdown).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.Created);
        (await PutAsync(account, id, 3, Payload(10, 2), limits, ArtifactKind.Markdown).ConfigureAwait(true)).ShouldBe(ArtifactPutOutcome.Quota);
    }

    private static byte[] Payload(int length, int salt)
    {
        var bytes = new byte[length];
        Array.Fill(bytes, (byte)'a');
        Encoding.ASCII.GetBytes(salt.ToString(System.Globalization.CultureInfo.InvariantCulture)).CopyTo(bytes, 0);
        return bytes;
    }

    private Task<ArtifactPutOutcome> PutAsync(string account, string id, int number, byte[] content, ArtifactOptions limits, ArtifactKind kind = ArtifactKind.Markdown) =>
        _directory!.PutAsync(account, id, number, kind, content, ArtifactWireContract.Hash(content), limits, Token);
}
